result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/funcalc.py", "content": """"funcalc -- a tiny calculator language with user-defined functions.

Programs are lines of two kinds:

    name(param, ...) = expression      (a function definition)
    expression                         (evaluated immediately)

Expressions support + - * / %, right-associative ^, parentheses,
function calls, and the ternary  cond ? a : b  where the condition
uses < > == and any non-zero value counts as true.

Recursion works (fib, mutual even/odd, ...); the interpreter keeps its
own call-depth counter so runaway recursion raises RecursionLimitError
instead of exhausting the Python stack.

    run(program_text, max_depth=200) -> [result, ...]   # bare expressions
"""

import re


# ------------------------------------------------------------------ errors

class CalcError(Exception):
    """Base class for all funcalc errors."""


class ParseError(CalcError):
    def __init__(self, message, line_no=None):
        self.line_no = line_no
        super().__init__(
            "line %s: %s" % (line_no, message) if line_no else message)


class EvalError(CalcError):
    pass


class UnknownFunctionError(EvalError):
    def __init__(self, name):
        self.name = name
        super().__init__("unknown function '%s'" % name)


class UnknownVariableError(EvalError):
    def __init__(self, name):
        self.name = name
        super().__init__("unknown variable '%s'" % name)


class ArityMismatchError(EvalError):
    def __init__(self, name, expected, got):
        self.name = name
        self.expected = expected
        self.got = got
        super().__init__(
            "function '%s' expects %d argument(s), got %d"
            % (name, expected, got))


class DivisionByZeroError(EvalError):
    pass


class RecursionLimitError(EvalError):
    def __init__(self, name):
        self.name = name
        super().__init__(
            "recursion limit exceeded while calling '%s'" % name)


# -------------------------------------------------------------- tokenizer

_TOKEN_RE = re.compile(r"""
    \s*(?:
        (?P<num>\d+\.\d*|\.\d+|\d+)
      | (?P<name>[A-Za-z_][A-Za-z0-9_]*)
      | (?P<op>==|[-+*/%^(),?:<>])
    )
""", re.VERBOSE)


def _tokenize(text, line_no=None):
    tokens = []
    pos = 0
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        if m is None:
            if text[pos:].strip() == "":
                break
            raise ParseError("unexpected character %r" % text[pos:].lstrip()[0],
                             line_no)
        pos = m.end()
        if m.group("num") is not None:
            s = m.group("num")
            value = float(s) if "." in s else int(s)
            tokens.append(("num", value))
        elif m.group("name") is not None:
            tokens.append(("name", m.group("name")))
        else:
            tokens.append(("op", m.group("op")))
    tokens.append(("end", None))
    return tokens


# ----------------------------------------------------------------- parser

class _Parser:
    """Recursive-descent parser producing an AST of nested tuples.

    AST nodes:  ("num", v)  ("var", name)  ("call", name, [args])
                ("neg", e)  ("bin", op, l, r)  ("if", c, a, b)
    """

    def __init__(self, tokens, line_no=None):
        self.tokens = tokens
        self.pos = 0
        self.line_no = line_no

    # -- helpers -----------------------------------------------------
    def peek(self):
        return self.tokens[self.pos]

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def accept(self, op):
        kind, val = self.peek()
        if kind == "op" and val == op:
            self.pos += 1
            return True
        return False

    def expect(self, op):
        if not self.accept(op):
            kind, val = self.peek()
            got = "end of line" if kind == "end" else repr(val)
            raise ParseError("expected %r, got %s" % (op, got), self.line_no)

    def expect_name(self):
        kind, val = self.next()
        if kind != "name":
            raise ParseError("expected identifier", self.line_no)
        return val

    def finish(self):
        kind, val = self.peek()
        if kind != "end":
            raise ParseError("unexpected token %r" % (val,), self.line_no)

    # -- grammar ------------------------------------------------------
    def expression(self):
        return self.ternary()

    def ternary(self):
        cond = self.comparison()
        if self.accept("?"):
            then = self.ternary()
            self.expect(":")
            other = self.ternary()
            return ("if", cond, then, other)
        return cond

    def comparison(self):
        node = self.additive()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("<", ">", "=="):
                self.next()
                node = ("bin", val, node, self.additive())
            else:
                return node

    def additive(self):
        node = self.term()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("+", "-"):
                self.next()
                node = ("bin", val, node, self.term())
            else:
                return node

    def term(self):
        node = self.unary()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("*", "/", "%"):
                self.next()
                node = ("bin", val, node, self.unary())
            else:
                return node

    def unary(self):
        if self.accept("-"):
            return ("neg", self.unary())
        if self.accept("+"):
            return self.unary()
        return self.power()

    def power(self):
        base = self.primary()
        if self.accept("^"):
            # right-associative; exponent may carry a unary sign
            return ("bin", "^", base, self.unary())
        return base

    def primary(self):
        kind, val = self.peek()
        if kind == "num":
            self.next()
            return ("num", val)
        if kind == "name":
            self.next()
            if self.accept("("):
                args = []
                if not self.accept(")"):
                    args.append(self.expression())
                    while self.accept(","):
                        args.append(self.expression())
                    self.expect(")")
                return ("call", val, args)
            return ("var", val)
        if self.accept("("):
            node = self.expression()
            self.expect(")")
            return node
        raise ParseError(
            "unexpected token %r" % (val,) if kind != "end"
            else "unexpected end of expression",
            self.line_no)


def parse_expression(text, line_no=None):
    p = _Parser(_tokenize(text, line_no), line_no)
    node = p.expression()
    p.finish()
    return node


# -------------------------------------------------------------- evaluator

def _truthy(value):
    return value != 0


def _divide(a, b):
    if b == 0:
        raise DivisionByZeroError()
    if isinstance(a, int) and isinstance(b, int) and a % b == 0:
        return a // b          # keep exact integer arithmetic exact
    return a / b


class _Interpreter:
    def __init__(self, functions, max_depth):
        self.functions = functions     # name -> (params tuple, ast)
        self.max_depth = max_depth
        self.depth = 0                 # our own call-depth counter

    def eval(self, node, env):
        tag = node[0]
        if tag == "num":
            return node[1]
        if tag == "var":
            try:
                return env[node[1]]
            except KeyError:
                raise UnknownVariableError(node[1])
        if tag == "neg":
            return -self.eval(node[1], env)
        if tag == "if":
            branch = node[2] if _truthy(self.eval(node[1], env)) else node[3]
            return self.eval(branch, env)
        if tag == "bin":
            op, left, right = node[1], node[2], node[3]
            a = self.eval(left, env)
            b = self.eval(right, env)
            if op == "+":
                return a + b
            if op == "-":
                return a - b
            if op == "*":
                return a * b
            if op == "/":
                return _divide(a, b)
            if op == "%":
                if b == 0:
                    raise DivisionByZeroError()
                return a % b
            if op == "^":
                return a ** b
            if op == "<":
                return 1 if a < b else 0
            if op == ">":
                return 1 if a > b else 0
            if op == "==":
                return 1 if a == b else 0
            raise EvalError("unknown operator '%s'" % op)
        if tag == "call":
            name, arg_nodes = node[1], node[2]
            if name not in self.functions:
                raise UnknownFunctionError(name)
            params, body = self.functions[name]
            if len(arg_nodes) != len(params):
                raise ArityMismatchError(name, len(params), len(arg_nodes))
            values = [self.eval(a, env) for a in arg_nodes]
            if self.depth >= self.max_depth:
                raise RecursionLimitError(name)
            self.depth += 1
            try:
                return self.eval(body, dict(zip(params, values)))
            finally:
                self.depth -= 1
        raise EvalError("bad AST node %r" % (node,))


# ------------------------------------------------------------------- run

_DEF_RE = re.compile(r"""
    \s*
    (?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*
    \((?P<params>[^()]*)\)\s*
    =(?!=)
""", re.VERBOSE)


def run(program_text, max_depth=200):
    """Execute a funcalc program.

    Lines matching ``name(p1, p2, ...) = expr`` define functions
    (later definitions override earlier ones); every other non-blank
    line is an expression whose value is collected in order.

    Returns the list of values of the bare expressions.
    """
    functions = {}
    results = []

    for i, raw_line in enumerate(program_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        m = _DEF_RE.match(line)
        if m:
            name = m.group("name")
            params = [p.strip() for p in m.group("params").split(",")
                      if p.strip()]
            if len(set(params)) != len(params):
                raise ParseError("duplicate parameter in '%s'" % name, i)
            body = parse_expression(line[m.end():], i)
            functions[name] = (tuple(params), body)
            continue

        ast = parse_expression(line, i)
        interp = _Interpreter(functions, max_depth)
        results.append(interp.eval(ast, {}))

    return results
"})
